class PmEditorTestBase : public ::testing::Test {
protected:
    PmEditor test_editor;
    PmEditor *self = &test_editor;
    SyntaxState syntax;

    void SetUp() override {
        // Common initialization
        pmeditor_restore_fn_pointers();
        ASSERT_EQ(kOk, pmeditor_init(self, NULL, 80, 25));

        // Mock pmeditor functions
        pmeditor_display_msg = pmeditor_test_display_msg;
        // pmeditor_print_line = pmeditor_test_print_line;
        pmeditor_print_lines = pmeditor_test_print_lines;

        // Initialize options
        mmb_options.syntax_highlight = true;
        mmb_options.tab = 4;
        mmb_options.break_key = 0;

        // Reset syntax state
        memset(&syntax, 0, sizeof(syntax));

        // Reset mock state
        memset(display_msg_capture, 0, sizeof(display_msg_capture));
        memset(self->keys, 0, sizeof(self->keys));
        print_lines_capture = { .calls = 0, .start = -1, .num = -1, .cy = -1 };

        // Initialize command and function token tables (for syntax highlighting)
        commandtbl_init();
        tokentbl_init();
    }

    void SetBuffer(const char* content) {
        strncpy(self->buf, content, EDIT_BUFFER_SIZE - 1);
        self->buf[EDIT_BUFFER_SIZE - 1] = '\0';

        // Count lines in the buffer
        self->num_lines = 1;
        for (const char *p = self->buf; *p; p++) {
            if (*p == '\n') self->num_lines++;
        }
    }

    void SetTxtp(int offset) {
        self->txtp = self->buf + offset;
        ASSERT_EQ(kOk, pmeditor_position_cursor(self, self->txtp));
    }

    void SetCursorAtEnd() {
        SetTxtp(strlen(self->buf));
    }

    void SetMark(int offset) {
        self->mark = self->buf + offset;
        ASSERT_EQ(kOk, pmeditor_position_cursor(self, self->mark));
    }
};

